fn in_range(c: char, table: &[(char, char)]) -> bool {
    use core::cmp::Ordering::*;
    table
        .binary_search_by(|&(low, high)| {
            if low > c {
                Greater
            } else if high < c {
                Less
            } else {
                Equal
            }
        })
        .is_ok()
}

